<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {api,roleNames} from '../api'
const tab=ref('users'),users=ref([]),configs=ref([]),logs=ref([]),search=ref(''),opened=ref(false),busy=ref(false)
const form=reactive({userId:null,userName:'',realName:'',email:'',phone:'',password:'',role:'student',status:'0'})
const filtered=computed(()=>users.value.filter(u=>`${u.userName} ${u.realName} ${u.email}`.includes(search.value)))
async function load(){[users.value,configs.value,logs.value]=await Promise.all([api('/admin/users'),api('/admin/config'),api('/admin/logs')])}
function open(u){Object.assign(form,{userId:u?.userId||null,userName:u?.userName||'',realName:u?.realName||'',email:u?.email||'',phone:u?.phone||'',password:'',role:u?.role||'student',status:u?.status||'0'});opened.value=true}
async function save(){busy.value=true;try{await api('/admin/users',{method:'POST',body:form});opened.value=false;ElMessage.success('账号已保存');await load()}catch{}finally{busy.value=false}}
async function saveConfig(row){await api('/admin/config/'+row.config_key,{method:'PUT',body:{value:row.config_value}});ElMessage.success('配置已更新');await load()}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">SYSTEM CONSOLE</div><h1>系统管理</h1><p class="muted">维护四类用户、基础配置与最近的核心操作记录。</p></div><el-button type="primary" @click="open(null)">＋ 新增用户</el-button></div>
  <el-tabs v-model="tab" class="section-tabs"><el-tab-pane label="用户与权限" name="users"/><el-tab-pane label="系统配置" name="config"/><el-tab-pane label="操作日志" name="logs"/></el-tabs>
  <section v-if="tab==='users'" class="surface"><div class="surface-title"><h3>用户列表</h3><el-input v-model="search" style="max-width:260px" placeholder="搜索账号、姓名或邮箱" clearable/></div><el-table :data="filtered"><el-table-column prop="userName" label="账号" width="140"/><el-table-column prop="realName" label="姓名" min-width="120"/><el-table-column label="角色" width="130"><template #default="{row}">{{roleNames[row.role]}}</template></el-table-column><el-table-column prop="email" label="邮箱" min-width="200"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='0'?'success':'info'">{{row.status==='0'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><p class="muted" style="margin-top:16px">账号有历史记录时以停用保留关联。修改密码、角色或状态后，目标用户需要重新登录。</p></section>
  <section v-else-if="tab==='config'" class="surface"><h3>基础参数</h3><el-table :data="configs"><el-table-column prop="config_key" label="配置键" min-width="280"/><el-table-column label="配置值" min-width="220"><template #default="{row}"><el-input v-model="row.config_value" :disabled="row.config_key==='upload.allowed_extensions'"/></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.config_key!=='upload.allowed_extensions'" link type="primary" @click="saveConfig(row)">保存</el-button><span v-else class="muted">固定白名单</span></template></el-table-column></el-table><p class="muted" style="margin-top:18px">文件上限1024至20971520字节；导出上限1至50000条；自动暂存间隔30至300秒，重新打开报名页后生效。</p></section>
  <section v-else class="surface"><div class="surface-title"><h3>最近100条操作日志</h3><el-button @click="load">刷新</el-button></div><el-table :data="logs" empty-text="暂无操作日志"><el-table-column prop="user_name" label="操作人" width="130"/><el-table-column prop="op_type" label="操作类型" min-width="160"/><el-table-column prop="op_content" label="内容" min-width="210"/><el-table-column prop="op_time" label="时间" min-width="190"/></el-table></section>
  <el-dialog v-model="opened" :title="form.userId?'维护用户':'新增用户'" width="550px"><el-form label-position="top"><el-form-item label="账号" required><el-input v-model="form.userName" :disabled="!!form.userId" maxlength="50" placeholder="3至50位字母、数字或下划线"/></el-form-item><el-form-item label="姓名" required><el-input v-model="form.realName" maxlength="50"/></el-form-item><el-form-item label="邮箱" required><el-input v-model="form.email" maxlength="100"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" maxlength="20"/></el-form-item><el-form-item :label="form.userId?'重置密码（留空保留原密码）':'初始密码'" :required="!form.userId"><el-input v-model="form.password" type="password" show-password placeholder="至少8位，包含字母和数字"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role" style="width:100%"><el-option v-for="(label,key) in roleNames" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="账号状态"><el-radio-group v-model="form.status"><el-radio value="0">正常</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="opened=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存用户</el-button></template></el-dialog>
</template>
